CREATE OR REPLACE FUNCTION public.temp_test_m30_pos(p_booking text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
        DECLARE
            v_lines TEXT[];
            v_line TEXT;
            v_i INT;
            v_airn_pos INT;
            v_date_str TEXT;
            v_day INT;
            v_mon_str TEXT;
            v_mon INT;
            v_year INT := EXTRACT(YEAR FROM CURRENT_TIMESTAMP)::INT;
            v_orig TEXT;
            v_dest TEXT;
            v_rest TEXT;
            v_airline TEXT;
            v_flight TEXT;
            v_class TEXT;
            v_dep_time TEXT;
            v_arr_time TEXT;
            v_check_in TIMESTAMP;
            v_check_out TIMESTAMP;
        BEGIN
            v_lines := string_to_array(p_Booking, E'
');
            FOR v_i IN 1 .. array_length(v_lines, 1) LOOP
                v_line := REPLACE(REPLACE(v_lines[v_i], E'', ''), E'﻿', '');
                IF v_line LIKE 'M30%' THEN
                    v_airn_pos := POSITION('AIRN' IN v_line);
                    IF v_airn_pos > 0 THEN
                        v_date_str := SUBSTRING(v_line FROM 10 FOR 5);
                        v_day := (SUBSTRING(v_date_str FROM 1 FOR 2))::INT;
                        v_mon_str := UPPER(SUBSTRING(v_date_str FROM 3 FOR 3));

                        v_mon := CASE v_mon_str
                            WHEN 'JAN' THEN 1 WHEN 'FEB' THEN 2 WHEN 'MAR' THEN 3
                            WHEN 'APR' THEN 4 WHEN 'MAY' THEN 5 WHEN 'JUN' THEN 6
                            WHEN 'JUL' THEN 7 WHEN 'AUG' THEN 8 WHEN 'SEP' THEN 9
                            WHEN 'OCT' THEN 10 WHEN 'NOV' THEN 11 WHEN 'DEC' THEN 12
                            ELSE 1 END;

                        v_orig := SUBSTRING(v_line FROM v_airn_pos + 4 FOR 3);
                        v_dest := SUBSTRING(v_line FROM v_airn_pos + 24 FOR 3);

                        v_rest := TRIM(SUBSTRING(v_line FROM v_airn_pos + 44));
                        -- v_rest is e.g. "AA 1381K 1250 1550  3.00..."
                        v_airline := SUBSTRING(v_rest FROM 1 FOR 2);
                        v_flight := TRIM(SUBSTRING(v_rest FROM 4 FOR 4));
                        v_class := SUBSTRING(v_rest FROM 8 FOR 1);
                        v_dep_time := SUBSTRING(v_rest FROM 10 FOR 4);
                        v_arr_time := SUBSTRING(v_rest FROM 15 FOR 4);

                        v_check_in := MAKE_TIMESTAMP(v_year, v_mon, v_day, (SUBSTRING(v_dep_time FROM 1 FOR 2))::INT, (SUBSTRING(v_dep_time FROM 3 FOR 2))::INT, 0);
                        v_check_out := MAKE_TIMESTAMP(v_year, v_mon, v_day, (SUBSTRING(v_arr_time FROM 1 FOR 2))::INT, (SUBSTRING(v_arr_time FROM 3 FOR 2))::INT, 0);
                        IF v_check_out < v_check_in THEN
                            v_check_out := v_check_out + INTERVAL '1 day';
                        END IF;

                        RAISE NOTICE 'M30 SEGMENT: Orig=%, Dest=%, Airline=%, Flight=%, Class=%, CheckIn=%, CheckOut=%',
                            v_orig, v_dest, v_airline, v_flight, v_class, v_check_in, v_check_out;
                    END IF;
                END IF;
            END LOOP;
        END $function$

temp_test_cc.definition:
CREATE OR REPLACE FUNCTION public.temp_test_cc(v_line text)
 RETURNS TABLE(card_type text, card_num text)
 LANGUAGE plpgsql
AS $function$
        DECLARE
            v_cc_pos INT;
            v_type TEXT := '';
            v_num TEXT := '';
            v_match TEXT[];
        BEGIN
            v_cc_pos := POSITION('CC' IN v_line);
            IF v_cc_pos > 0 THEN
                v_type := SUBSTRING(v_line FROM v_cc_pos + 2 FOR 2);
                v_match := regexp_matches(SUBSTRING(v_line FROM v_cc_pos + 4), '^([0-9]{10,16})');
                IF array_length(v_match, 1) >= 1 THEN
                    v_num := v_match[1];
                END IF;
            END IF;
            RETURN QUERY SELECT v_type, v_num;
        END $function$

fn_calcular_porcentaje_comision.definition:
CREATE OR REPLACE FUNCTION public.fn_calcular_porcentaje_comision(p_utilidad double precision, p_valor_base double precision)
 RETURNS double precision
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF COALESCE(p_valor_base, 0.0) = 0.0 THEN
        RETURN 0.0;
    END IF;
    RETURN (COALESCE(p_utilidad, 0.0) / p_valor_base) * 100.0;
END;
$function$

