		--p_am_TarifaContado := p_am_TarifaContado+p_am_comb;
	 --END IF;
	--IF p_am_TarifaCredito>0 and p_am_TarifaContado = 0 THEN
		--p_am_TarifaCredito := p_am_TarifaCredito+p_am_comb;
	 --end IF;

	 --p_am_vat := p_am_vat-p_am_comb;
