					WHERE b.id = p_Id_BookingGDS
					AND p.state = 'NUEVO';

					IF ((p_bl_usada = 0 AND NOT EXISTS (SELECT * FROM public."BookingsGDSEnvoiceAuto" where "bookingId" = p_Id_BookingGDS))
						OR NOT EXISTS (SELECT *
										FROM public."BookingProductGDS" p
										INNER JOIN public."BookingGDS" b on b.id = p."bookingId"
										WHERE b.id = p_Id_BookingGDS))
						AND p_gds = 1 THEN
						INSERT INTO public."BookingsGDSEnvoiceAuto" (branch,implant,"bookingCode" ,"bookingId") 
						VALUES(p_branch,p_implant,p_code, p_Id_BookingGDS);
					END IF;
				-----------------------------------------------------------------------------------------
				---------------------------------------------------------------------------------------------
				IF EXISTS (Select * From public."BookingProductItineraryGDS" Where "bookingId" = p_Id_BookingGDS) THEN
					   Delete From public."BookingProductItineraryGDS" WHERE "bookingId" = p_Id_BookingGDS;
					END IF;
				--------------------------------------------------------------------------------------------

				If p_error<>0 THEN
					RAISE EXCEPTION 'Error al Guardar los Datos de Cabecera de la Booking GDS';
					-- -- SELECT -1;
					Return;
				END IF;

				------------------------------------------------------------------------------------------
				-- Log de Bookings -----------------------------------------------------------------------
				------------------------------------------------------------------------------------------
				INSERT INTO public."BookingsGDS_log" (blanch,implant,message,"file","codebooking", "booking","error")
				SELECT 
					p_branch
					,p_implant
					,'Log Booking'
					,p_code
					,p_code
					,p_booking
					,0;

				IF p_gds NOT IN (6,8,9) THEN
					p_id_out := p_Id_BookingGDS;
					RETURN;
				END IF;

				--IF EXISTS (SELECT * FROM public."SystemParameter" Where code = '565' AND LTRIM(RTRIM(value)) = 'S') THEN
				--	UPDATE public."BookingGDS" SET cd_formapago_cliente = (SELECT c.code_fp 
				--								  FROM public."Configuracion_remisiones_FPago" c
				--								  INNER JOIN public."Configuracion_remisiones" e ON e.id_cliente = c.id_cliente
				--								  WHERE (c.id_cliente = p_client OR c.id_cliente = p_ds_cliid)
				--									AND e.bl_forma_pago = 1
				--									AND c.bl_defecto = 1
				--								  LIMIT 1)
				--	WHERE id = p_Id_BookingGDS;
				--END IF; 

				p_id_out := p_Id_BookingGDS;
				RETURN;
			END IF;
		END IF;
		p_id_out := p_Id_BookingGDS;
		RETURN;
	END IF;

	IF p_Op IN ('flight', 'car', 'hotel', 'insurance', 'product') THEN
		-- Determinamos la nacionalidad si no viene por parametro
		IF p_inNationality IS NULL THEN
			v_inNationality := 1;
			IF EXISTS (SELECT A.id FROM public."Airports" A 
			  INNER JOIN public."Cities" C ON C.id = A."citiesId"
			  INNER JOIN public."Countries" P ON P.id = C."countriesId"
			  INNER JOIN public."SystemParameter" PR ON PR.code = 'Pais' AND PR.value<>P.name 
			  WHERE A.code = COALESCE(p_cd_citysalida, p_origin, p_cd_city, ''))
			THEN
				v_inNationality := 2;
			ELSE
				v_inNationality := 1;
			END IF;
		ELSE
			v_inNationality := p_inNationality;
		END IF;

		-- 1. Insertamos el Producto
		INSERT INTO public."BookingProductGDS" (
			"bookingId", code, type, "service", "description", 
			"prestadoracode", "prestadorainitials", "prestadoradist", "provider", 
			"quantity", price, cost, "checkInDate", "checkOutDate", 
			"nights", "paxAdults", "paxChildren", "serviceType", "billingConcept", 
			"destination", "reservationCode", "sellerCom", "ticketPrinterCom", 
			"inNationality", "state", "conjunction", "revised", "typeproduct", "penalty", consecutive
		) VALUES (
			p_bookingId, 
			COALESCE(p_code, ''), 
			COALESCE(p_productType, CASE WHEN p_Op = 'flight' THEN 'Tiquete' WHEN p_Op = 'car' THEN 'car' WHEN p_Op = 'hotel' THEN 'hotel' WHEN p_Op = 'insurance' THEN 'insurance' ELSE '' END), 
			COALESCE(p_productService, CASE WHEN p_Op = 'flight' THEN 'Tiquete Aereo' WHEN p_Op = 'car' THEN 'Renta de Auto' WHEN p_Op = 'hotel' THEN 'Alojamiento' WHEN p_Op = 'insurance' THEN 'Seguros' ELSE '' END), 
			COALESCE(p_productDescription, CASE WHEN p_Op = 'flight' THEN 'Emision de Tiquete' WHEN p_Op = 'car' THEN 'Servicio de Renta de Auto' WHEN p_Op = 'hotel' THEN 'Reserva de Hotel' WHEN p_Op = 'insurance' THEN 'Servicio de seguros' ELSE '' END),
			p_prestadoraCode, 
			p_prestadoraInitials, 
			p_prestadoraDist, 
			p_provider,
			COALESCE(p_quantity, 1), 
			COALESCE(p_amount, 0), 
			COALESCE(p_cost, 0), 
			p_checkInDate, 
			p_checkOutDate, 
			p_nights, 
			p_paxAdults, 
			p_paxChildren, 
			p_serviceType, 
			p_billingConcept, 
			p_destination, 
			p_code, 
			p_sellerCom, 
			p_ticketPrinterCom, 
			v_inNationality, 
			COALESCE(p_status, 'NUEVO'), 
			p_conjunction, 
			p_revised, 
			p_typeproduct, 
			p_penalty,
			p_consecutive
		) RETURNING id INTO v_BookingProductId;

		-- 2. Insertamos el Pasajero (Solo si viene en el mismo llamado)
		--IF COALESCE(p_firstName, '') <> '' THEN
		--	INSERT INTO public."BookingProductPassangerGDS" (
		--		"bookingProductId", "firstnm", "lastnm", "prefix", "identification", "phone", "email"
		--	) VALUES (
		--		v_BookingProductId, p_firstName, p_lastName, p_documentType, p_identification, p_phone, p_email
		--	);
		--END IF;

		p_id_out := v_BookingProductId;
		RETURN;
	END IF;


	IF p_Op = 'itinerary' THEN
		v_fecha_salida := p_ds_fecha_salida;
		-- Lógica de ajuste de año (legacy)
		IF LENGTH(v_fecha_salida) >= 8 THEN
			v_Y := SUBSTRING(v_fecha_salida, 1, 4);
			v_M := SUBSTRING(v_fecha_salida, 5, 2);
			v_D := SUBSTRING(v_fecha_salida, 7, 2);
			SELECT EXTRACT(MONTH FROM "date")::INTEGER, EXTRACT(YEAR FROM "date")::INTEGER 
			INTO v_Mr, v_YAr
			FROM public."BookingGDS" WHERE id = p_bookingId;

			IF (v_Mr > v_M::INTEGER AND v_YAr >= v_Y::INTEGER) THEN
				v_Yr := v_Y::INTEGER + 1;
				v_Y := v_Yr::TEXT;
			END IF;

			v_fecha_salida := v_Y || LPAD(v_M, 2, '0') || LPAD(v_D, 2, '0');
		END IF;

		-- Construir Timestamps
		v_checkIn := TO_TIMESTAMP(v_fecha_salida || ' ' || COALESCE(p_ds_hora_salida, '00:00'), 'YYYYMMDD HH24:MI');
		v_checkOut := TO_TIMESTAMP(v_fecha_salida || ' ' || COALESCE(p_ds_hora_llegada, '00:00'), 'YYYYMMDD HH24:MI');
		INSERT INTO public."BookingProductItineraryGDS" (
			"bookingProductId",
			"orden",
			"origin",
			"destination",
			"class",
			"checkInDate",
			"checkOutDate",
			"terminal",
			"prestadoraCode",
			"farebasis",
			"Numflight",
			"Typeflight",
			"amount"
		) VALUES (
			COALESCE(p_bookingProductId, (SELECT MAX(id) FROM public."BookingProductGDS" WHERE "bookingId" = p_bookingId)),
			p_orden,
			p_origin,
			p_destination,
			LEFT(p_class, 1),
			v_checkIn,
			v_checkOut,
			COALESCE(p_terminal, p_destination), -- terminal
			COALESCE(p_prestadoraCode, ''),
			COALESCE(p_farebasis, ''),
			p_Numflight,
			p_Typeflight,
			COALESCE(p_amount, 0)
		);

		p_id_out := p_bookingId;
		RETURN;
	END IF;


	--IF p_Op = 'Poliza' THEN
	--	INSERT INTO public."BookingProductVariableGDS"("bookingProductId", code, name, "value")
	--	VALUES (p_bookingProductId, 'POLIZA', 'Poliza', COALESCE(p_policy, ''));
	--END IF;

	IF p_Op IN ('passanger') THEN
		INSERT INTO public."BookingProductPassangerGDS"("bookingProductId", "firstnm", "lastnm", "prefix", "identification", "phone", "email")
		VALUES (COALESCE(p_bookingProductId, (SELECT MAX(id) FROM public."BookingProductGDS" WHERE "bookingId" = p_bookingId)), p_firstName, p_lastName, p_documentType, p_identification, p_phone, p_email);

		p_id_out := p_bookingId;
		RETURN;
	END IF;

	IF p_Op = 'var' THEN 
		INSERT INTO public."BookingProductVariableGDS"("bookingProductId", code, name, "value")
		VALUES (p_bookingProductId, COALESCE(p_varName, 'VAR'), p_varName, p_varValue);
	END IF;

	IF p_Op = 'tax' THEN
		INSERT INTO public."BookingProductTaxGDS"("bookingProductId", code, name, type, ismain, percentage, amount)
		VALUES (p_bookingProductId, COALESCE(p_taxCode, 'TAX'), COALESCE(p_taxName, 'Impuesto'), COALESCE(p_taxType, 'IMP'), p_taxismain, COALESCE(p_perTax, 0), p_tax);
	END IF;

	IF p_Op = 'payment' THEN
		INSERT INTO public."BookingProductPaymentGDS"(
			"bookingProductId", code, name, type, "typecreditcard", "numbercreditcard", 
			"vouchercreditcard", "expiredcreditcard", "authcreditcard", "quotas", 
			"bank", "square", "reference", "policy", "policyannex", amount
		)
		VALUES (
			p_bookingProductId, COALESCE(p_paymentCode, 'PAG'), COALESCE(p_paymentName, 'Pago'), COALESCE(p_paymentType, 'EFECTIVO'), p_creditCardType, p_creditCardNumber, 
			p_voucher, p_expirationDate, p_authorization, p_quotas, 
			p_bank, p_square, p_reference, p_policy, p_policyAnnex, p_amount
		);
	END IF;

	IF p_Op = 'FEE' THEN
		INSERT INTO public."BookingProductFEEGDS"(
			"bookingProductId", code, name, type, "description", "billigconcept", "servicetype", amount, tax, other, total
		)
		VALUES (
			p_bookingProductId, COALESCE(p_feeCode, 'FEE'), COALESCE(p_feeName, 'Fee'), COALESCE(p_feeType, 'FEE'), COALESCE(p_feeDescription, ''), 
			COALESCE(p_feeBillingConcept, '1'), COALESCE(p_feeServiceType, '1'), p_amount, 0, 0, p_amount
		);
	END IF;

	p_id_out := NULL;
	RETURN;
END;
$procedure$

temp_test_sabre.definition:
CREATE OR REPLACE FUNCTION public.temp_test_sabre(p_file text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
        DECLARE
            v_lines TEXT[];
            v_line TEXT;
            v_i INT;
            v_code VARCHAR(10);
        BEGIN
            v_lines := string_to_array(p_file, E'
');
            RAISE NOTICE 'Line count: %', array_length(v_lines, 1);
            FOR v_i IN 1 .. array_length(v_lines, 1) LOOP
                v_line := REPLACE(v_lines[v_i], E'', '');
                IF v_line LIKE 'AA%' THEN
                    v_code := NULLIF(TRIM(SUBSTRING(v_line FROM 56 FOR 6)), '');
                    RAISE NOTICE 'Found AA line! Length: %, SUBSTRING(56,6): [%]', length(v_line), v_code;
                END IF;
            END LOOP;
        END $function$

temp_test_lines.definition:
CREATE OR REPLACE FUNCTION public.temp_test_lines(p_booking text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
        DECLARE
            v_lines TEXT[];
            v_line TEXT;
            v_i INT;
            v_code TEXT := NULL;
        BEGIN
            v_lines := string_to_array(p_Booking, E'
');
            RAISE NOTICE 'Array length: %', array_length(v_lines, 1);
            FOR v_i IN 1 .. array_length(v_lines, 1) LOOP
                v_line := REPLACE(REPLACE(v_lines[v_i], E'', ''), E'﻿', '');
                IF v_i <= 5 THEN
                    RAISE NOTICE 'Line % (len %): [%]', v_i, length(v_line), SUBSTRING(v_line FROM 1 FOR 40);
                END IF;
                IF v_line LIKE 'AA%' THEN
                    v_code := NULLIF(TRIM(SUBSTRING(v_line FROM 56 FOR 6)), '');
                    RAISE NOTICE 'AA MATCH! v_code = %', v_code;
                END IF;
            END LOOP;
        END $function$

fnCreditCardValidar.definition:
CREATE OR REPLACE FUNCTION public."fnCreditCardValidar"(p_referencia text)
 RETURNS TABLE(es_valido boolean, codigo_tarjeta text, numero_tarjeta text, tarjeta_id integer, nombre_tarjeta text, mensaje text)
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_code text;
    v_number text;
    v_id integer;
    v_name text;
BEGIN
    IF p_referencia IS NULL OR TRIM(p_referencia) = '' THEN
        RETURN QUERY SELECT true, ''::text, ''::text, NULL::integer, ''::text, 'OK'::text;
        RETURN;
    END IF;

    p_referencia := TRIM(p_referencia);

    -- Si tiene al menos 2 caracteres iniciales que son letras (ej: VI0000000000007023)
    IF length(p_referencia) >= 2 AND substring(p_referencia from 1 for 2) ~ '^[A-Za-z]{2}$' THEN
        v_code := UPPER(substring(p_referencia from 1 for 2));
        v_number := substring(p_referencia from 3);

        SELECT c.id, c.name INTO v_id, v_name
        FROM public."CreditCard" c
        WHERE UPPER(TRIM(c.code)) = v_code AND c.inactive = false
        LIMIT 1;

        IF v_id IS NOT NULL THEN
            RETURN QUERY SELECT true, v_code, v_number, v_id, v_name, 'SUCCESS'::text;
        ELSE
            RETURN QUERY SELECT false, v_code, v_number, NULL::integer, ''::text, ('El código de tarjeta "' || v_code || '" no existe en el Maestro de Tarjetas de Crédito.')::text;
        END IF;
    ELSE
        -- Si son solo números o no empieza por código de 2 letras
        RETURN QUERY SELECT true, ''::text, p_referencia, NULL::integer, ''::text, 'Sin código de tipo de tarjeta'::text;
    END IF;
END;
$function$

fnEquivalenceInterface.definition:
CREATE OR REPLACE FUNCTION public."fnEquivalenceInterface"(p_id_interface integer, p_id_master integer, p_value text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_equivalence TEXT;
    v_master_code TEXT;
BEGIN
    -- Si el valor es nulo o vacío, retornamos el mismo valor
    IF p_value IS NULL OR trim(p_value) = '' THEN
        RETURN p_value;
    END IF;

    -- Buscamos el equivalente en la tabla EquivalencesInterfaces
    SELECT cd_codigo 
    INTO v_equivalence
    FROM public."EquivalencesInterfaces"
    WHERE id_interfaces = p_id_interface
      AND id_master = p_id_master
      AND cd_codigoInte = p_value
    LIMIT 1;

    -- Si no se encuentra equivalencia:
    IF v_equivalence IS NULL OR trim(v_equivalence) = '' THEN
        -- Si corresponde al maestro de Impuestos (ChargeAndTax), mapear por defecto a 'OTR' (Otros Impuestos)
        SELECT code INTO v_master_code FROM public."Master" WHERE id = p_id_master LIMIT 1;
        IF v_master_code = 'ChargeAndTax' THEN
            RETURN 'OTR';
        ELSE
            RETURN p_value;
        END IF;
    ELSE
        RETURN v_equivalence;
    END IF;
END;
$function$

fnInterfaceExtractParamValue.definition:
CREATE OR REPLACE FUNCTION public."fnInterfaceExtractParamValue"(p_interface_id integer, p_field_code text, p_booking_file text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_prefix TEXT;
    v_delimiter TEXT;
    v_start_pos INTEGER;
    v_length INTEGER;
    v_line TEXT;
    v_extracted TEXT := NULL;
    v_pos INTEGER;
    v_lines TEXT[];
    i INTEGER;
BEGIN
    IF p_booking_file IS NULL OR TRIM(p_booking_file) = '' THEN
        RETURN NULL;
    END IF;

    -- 1. Buscar regla parametrizada para la interfaz y código de campo
    SELECT "prefix", "delimiter", "startPosition", "length"
    INTO v_prefix, v_delimiter, v_start_pos, v_length
    FROM public."InterfaceExtractParam"
    WHERE "interfaceId" = p_interface_id
      AND UPPER("fieldCode") = UPPER(TRIM(p_field_code))
      AND "isActive" = TRUE
    ORDER BY id DESC
    LIMIT 1;

    -- Fallbacks por defecto si no hay regla configurada
    IF v_prefix IS NULL OR v_prefix = '' THEN
        IF UPPER(TRIM(p_field_code)) = 'CLIENT' THEN
            v_prefix := 'RM*NC-';
        ELSIF UPPER(TRIM(p_field_code)) = 'SELLER' THEN
            v_prefix := 'RM*VEN-';
        ELSIF UPPER(TRIM(p_field_code)) = 'TICKETPRINTER' THEN
            v_prefix := 'RM*TK-';
        ELSIF UPPER(TRIM(p_field_code)) = 'BRANCH' THEN
            v_prefix := 'RM*SUC-';
        ELSIF UPPER(TRIM(p_field_code)) = 'IMPLANT' THEN
            v_prefix := 'RM*IMP-';
        ELSE
            RETURN NULL;
        END IF;
    END IF;

    IF v_delimiter IS NULL THEN
        v_delimiter := '-';
    END IF;

    -- 2. Dividir archivo en líneas
    v_lines := string_to_array(p_booking_file, E'\n');

    -- 3. Recorrer líneas buscando el prefijo constante
    FOR i IN 1..array_length(v_lines, 1) LOOP
        v_line := TRIM(v_lines[i]);
        v_line := REPLACE(v_line, E'\r', '');

        v_pos := POSITION(v_prefix IN v_line);
        IF v_pos = 0 AND UPPER(TRIM(p_field_code)) = 'SELLER' THEN
            v_pos := POSITION('RM*VE-' IN v_line);
            IF v_pos > 0 THEN v_prefix := 'RM*VE-'; END IF;
        END IF;
        IF v_pos = 0 AND UPPER(TRIM(p_field_code)) = 'TICKETPRINTER' THEN
            v_pos := POSITION('RM*ASE-' IN v_line);
            IF v_pos > 0 THEN v_prefix := 'RM*ASE-'; END IF;
        END IF;
        IF v_pos > 0 THEN
            v_extracted := SUBSTRING(v_line FROM v_pos + CHAR_LENGTH(v_prefix));
            v_extracted := TRIM(v_extracted);

            IF v_delimiter IS NOT NULL AND v_delimiter <> '' THEN
                v_pos := POSITION(v_delimiter IN v_extracted);
                IF v_pos > 1 THEN
                    v_extracted := SUBSTRING(v_extracted FROM 1 FOR v_pos - 1);
                END IF;
            END IF;

            IF v_length IS NOT NULL AND v_length > 0 AND CHAR_LENGTH(v_extracted) > v_length THEN
                v_extracted := SUBSTRING(v_extracted FROM 1 FOR v_length);
            END IF;

            v_extracted := TRIM(v_extracted);
            IF v_extracted <> '' THEN
                RETURN v_extracted;
            END IF;
        END IF;
    END LOOP;

    RETURN NULL;
END;
$function$

fnObtenerSiguienteConsecutivo.definition:
CREATE OR REPLACE FUNCTION public."fnObtenerSiguienteConsecutivo"(p_transaction_type text, p_branch_id integer DEFAULT NULL::integer, p_implant_id integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_rec RECORD;
    v_next_val integer;
    v_prefix text := '';
    v_padding integer := 0;
    v_num_str text;
    v_formatted text;
    v_res_json jsonb;
    v_norm_type text;
BEGIN
    v_norm_type := UPPER(TRIM(COALESCE(p_transaction_type, 'INVOICE')));

    -- 1. Intentar buscar un consecutivo específico para la combinación sucursal e implante
    SELECT * INTO v_rec
    FROM public."TransactionConsecutive"
    WHERE "isActive" = true
      AND (
          UPPER("transactionType") = v_norm_type
          OR (v_norm_type IN ('INVOICE', 'FACTURA', 'FACTURACION', 'FACTURACION ELECTRONICA') AND UPPER("transactionType") IN ('INVOICE', 'FACTURA', 'FACTURACION', 'FACTURACION ELECTRONICA'))
          OR (v_norm_type IN ('QUOTATION', 'COTIZACION') AND UPPER("transactionType") IN ('QUOTATION', 'COTIZACION'))
          OR (v_norm_type IN ('PREQUOTATION', 'PRECOTIZACION') AND UPPER("transactionType") IN ('PREQUOTATION', 'PRECOTIZACION'))
          OR (v_norm_type IN ('CREDIT_NOTE', 'NOTA_CREDITO') AND UPPER("transactionType") IN ('CREDIT_NOTE', 'NOTA_CREDITO'))
      )
      AND (
          (p_branch_id IS NOT NULL AND "branchId" = p_branch_id)
          OR ("branchId" IS NULL)
      )
      AND (
          (p_implant_id IS NOT NULL AND "implantId" = p_implant_id)
          OR ("implantId" IS NULL)
      )
    ORDER BY 
        CASE WHEN p_implant_id IS NOT NULL AND "implantId" = p_implant_id THEN 1 WHEN "implantId" IS NOT NULL THEN 3 ELSE 2 END,
        CASE WHEN p_branch_id IS NOT NULL AND "branchId" = p_branch_id THEN 1 WHEN "branchId" IS NOT NULL THEN 3 ELSE 2 END,
        id ASC
    LIMIT 1
    FOR UPDATE;

    -- Si existe un registro configurado
    IF v_rec.id IS NOT NULL THEN
        v_next_val := COALESCE(v_rec."currentNumber", v_rec."initialNumber", 1);
        v_prefix := COALESCE(TRIM(v_rec.prefix), '');
        v_padding := COALESCE(v_rec.padding, 0);

        -- Incrementar atómicamente para la siguiente transacción
        UPDATE public."TransactionConsecutive"
        SET "currentNumber" = "currentNumber" + 1,
            "updatedAt" = CURRENT_TIMESTAMP
        WHERE id = v_rec.id;
    ELSE
        -- Fallback si no existe parámetro de consecutivo configurado todavía
        v_prefix := CASE 
            WHEN v_norm_type IN ('QUOTATION', 'COTIZACION') THEN 'COT'
            WHEN v_norm_type IN ('INVOICE', 'FACTURA', 'FACTURACION') THEN 'FAC'
            WHEN v_norm_type IN ('CREDIT_NOTE', 'NOTA_CREDITO') THEN 'NC'
            ELSE 'DOC'
        END;

        IF v_norm_type IN ('QUOTATION', 'COTIZACION') THEN
            SELECT COALESCE(MAX(id), 0) + 1 INTO v_next_val FROM public."Quotation";
        ELSE
            SELECT COALESCE(MAX(id), 0) + 1 INTO v_next_val FROM public."Invoices";
        END IF;
    END IF;

    v_num_str := v_next_val::text;
    IF v_padding > 0 AND length(v_num_str) < v_padding THEN
        v_num_str := lpad(v_num_str, v_padding, '0');
    END IF;

    IF v_prefix <> '' THEN
        IF v_prefix LIKE '%-' OR v_prefix LIKE '%/' THEN
            v_formatted := v_prefix || v_num_str;
        ELSE
            v_formatted := v_prefix || '-' || v_num_str;
        END IF;
    ELSE
        v_formatted := v_num_str;
    END IF;

    v_res_json := jsonb_build_object(
        'consecutivoNumber', v_next_val,
        'prefix', v_prefix,
        'formattedConsecutive', v_formatted,
        'consecutivoId', v_rec.id
    );

    RETURN v_res_json;
END;
$function$

fnReportDinamic.definition:
CREATE OR REPLACE FUNCTION public."fnReportDinamic"(p_report_id integer, p_filter_values json DEFAULT '{}'::json)
 RETURNS json
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_base_table VARCHAR;
    v_custom_sql TEXT;
    v_sql TEXT;
    v_select_clause TEXT;
    v_from_clause TEXT;
    v_where_clause TEXT := '1=1';
    v_order_col VARCHAR;
    v_order_dir VARCHAR;
    v_result json;
    v_filter RECORD;
    v_val TEXT;
    v_val_to TEXT;
BEGIN
    -- 1. Obtener la configuración del reporte
    SELECT base_table, custom_sql INTO v_base_table, v_custom_sql
    FROM public."Report"
    WHERE id = p_report_id;

    IF v_base_table IS NULL AND v_custom_sql IS NULL THEN
        RAISE EXCEPTION 'Reporte no encontrado';
    END IF;

    -- 2. Construir el Origen de Datos (Custom SQL o Tabla Base)
    IF v_custom_sql IS NOT NULL AND v_custom_sql <> '' THEN
        -- Si hay SQL personalizado, lo usamos como fuente
        v_from_clause := '(' || v_custom_sql || ') t1 ';
        v_select_clause := '*';
    ELSE
        -- 2.1 Construir el SELECT (Columnas Visibles)
        SELECT string_agg(
            CASE 
                WHEN is_calculated THEN formula_expression || ' AS "' || COALESCE(alias, 'Calculado') || '"'
                ELSE COALESCE(table_alias || '.', '') || '"' || column_name || '"' || ' AS "' || COALESCE(alias, column_name) || '"'
            END,
            ', ' ORDER BY sort_order ASC
        ) INTO v_select_clause
        FROM public."ReportColumns"
        WHERE report_id = p_report_id AND is_visible = true;

        IF v_select_clause IS NULL THEN
            v_select_clause := '*'; 
        END IF;

        -- 2.2 Construir el FROM y los JOINS
        v_from_clause := 'public."' || v_base_table || '" t1 ';

        SELECT v_from_clause || string_agg(
            join_type || ' public."' || table_name || '" ' || alias || ' ON ' || join_condition,
            ' ' ORDER BY sort_order ASC
        ) INTO v_from_clause
        FROM public."ReportJoins"
        WHERE report_id = p_report_id;

        IF v_from_clause IS NULL THEN
            v_from_clause := 'public."' || v_base_table || '" t1 ';
        END IF;
    END IF;

    -- 4. Construir el WHERE (Filtros Dinámicos con Rangos)
    FOR v_filter IN SELECT * FROM public."ReportFilters" WHERE report_id = p_report_id LOOP
        v_val := p_filter_values->>(COALESCE(v_filter.table_alias, 't1') || '.' || v_filter.column_name);
        v_val_to := p_filter_values->>(COALESCE(v_filter.table_alias, 't1') || '.' || v_filter.column_name || '_to');
        
        DECLARE
            v_field_expr TEXT;
        BEGIN
            -- Determinar la expresión del campo
            IF v_custom_sql IS NOT NULL AND v_custom_sql <> '' THEN
                -- En Custom SQL, si el usuario puso algo como q."date", 
                -- debemos quitar el "q." porque afuera solo existe el alias "t1"
                IF v_filter.column_name ~ '\.' THEN
                    v_field_expr := 't1."' || split_part(v_filter.column_name, '.', 2) || '"';
                    -- Limpiar comillas si el split_part las dejó
                    v_field_expr := replace(v_field_expr, '"', ''); 
                    -- Re-envolver con comillas de forma segura
                    v_field_expr := 't1."' || v_field_expr || '"';
                ELSE
                    v_field_expr := 't1."' || v_filter.column_name || '"';
                END IF;
            ELSIF v_filter.column_name ~ '["\.]' THEN
                v_field_expr := v_filter.column_name;
            ELSE
                v_field_expr := COALESCE(v_filter.table_alias, 't1') || '."' || v_filter.column_name || '"';
            END IF;

            IF (v_val IS NOT NULL AND v_val <> '') OR (v_val_to IS NOT NULL AND v_val_to <> '') THEN
                IF v_filter.filter_type = 'date' THEN
                    IF v_val IS NOT NULL AND v_val <> '' AND v_val_to IS NOT NULL AND v_val_to <> '' THEN
                        v_where_clause := v_where_clause || ' AND ' || v_field_expr || ' BETWEEN ''' || v_val || '''::date AND ''' || v_val_to || '''::date';
                    ELSIF v_val IS NOT NULL AND v_val <> '' THEN
                        v_where_clause := v_where_clause || ' AND ' || v_field_expr || ' >= ''' || v_val || '''::date';
                    ELSIF v_val_to IS NOT NULL AND v_val_to <> '' THEN
                        v_where_clause := v_where_clause || ' AND ' || v_field_expr || ' <= ''' || v_val_to || '''::date';
                    END IF;
                ELSIF v_filter.filter_type = 'number' THEN
                    IF v_val IS NOT NULL AND v_val <> '' AND v_val_to IS NOT NULL AND v_val_to <> '' THEN
                        v_where_clause := v_where_clause || ' AND ' || v_field_expr || ' BETWEEN ' || v_val || ' AND ' || v_val_to;
                    ELSIF v_val IS NOT NULL AND v_val <> '' THEN
                        v_where_clause := v_where_clause || ' AND ' || v_field_expr || ' >= ' || v_val;
                    ELSIF v_val_to IS NOT NULL AND v_val_to <> '' THEN
                        v_where_clause := v_where_clause || ' AND ' || v_field_expr || ' <= ' || v_val_to;
                    END IF;
                ELSE -- text / like
                    v_where_clause := v_where_clause || ' AND ' || v_field_expr || ' ILIKE ''%' || v_val || '%''';
                END IF;
            END IF;
        END;
    END LOOP;

    -- 5. Ensamblar SQL Final con Ordenamiento Múltiple
    v_sql := 'SELECT json_agg(row_to_json(t)) FROM (SELECT ' || v_select_clause || ' FROM ' || v_from_clause || ' WHERE ' || v_where_clause;
    
    -- Agregar ORDER BY si está definido (Múltiple)
    DECLARE
        v_order_by TEXT;
    BEGIN
        SELECT string_agg(
            CASE 
                WHEN column_expr ~ '^[a-zA-Z0-9_]+\.[a-zA-Z0-9_]+$' THEN -- Formato t1.columna
                    split_part(column_expr, '.', 1) || '."' || split_part(column_expr, '.', 2) || '"'
                ELSE column_expr 
            END || ' ' || direction, 
            ', ' ORDER BY sort_order ASC
        ) INTO v_order_by
        FROM public."ReportSorts" WHERE report_id = p_report_id;
        
        IF v_order_by IS NOT NULL THEN
            v_sql := v_sql || ' ORDER BY ' || v_order_by;
        END IF;
    END;

    v_sql := v_sql || ') t';

    -- 6. Ejecutar dinámicamente
    EXECUTE v_sql INTO v_result;

    IF v_result IS NULL THEN
        v_result := '[]'::json;
    END IF;

    RETURN v_result;
END;
$function$

fn_obtener_decimales_moneda.definition:
CREATE OR REPLACE FUNCTION public.fn_obtener_decimales_moneda(p_currency_code text)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_decimals INT;
BEGIN
    SELECT COALESCE(decimals, 2) INTO v_decimals
    FROM public."Currency"
    WHERE LOWER(code) = LOWER(p_currency_code);
    
    RETURN COALESCE(v_decimals, 2);
END;
$function$

spAirportActualizar.definition:
CREATE OR REPLACE PROCEDURE public."spAirportActualizar"(IN p_id integer, IN p_code text, IN p_name text, IN p_citiesid integer, IN p_user_id integer, INOUT p_mensaje_resultado text)
 LANGUAGE plpgsql
AS $procedure$
DECLARE v_existente integer;
BEGIN
    SELECT id INTO v_existente FROM public."Airports" WHERE id = p_id;
    IF v_existente IS NULL THEN p_mensaje_resultado := 'ERROR: No existe.'; RETURN; END IF;
    SELECT id INTO v_existente FROM public."Airports" WHERE "code" = p_code AND id <> p_id;
    IF v_existente IS NOT NULL THEN p_mensaje_resultado := 'ERROR: El código ya existe.'; RETURN; END IF;
    UPDATE public."Airports" SET "code" = COALESCE(TRIM(p_code), ''), "name" = TRIM(p_name), "citiesId" = p_citiesId WHERE id = p_id;
    p_mensaje_resultado := 'SUCCESS';
EXCEPTION WHEN OTHERS THEN p_mensaje_resultado := 'ERROR: ' || SQLERRM; END; $procedure$

spAirportCrear.definition:
CREATE OR REPLACE PROCEDURE public."spAirportCrear"(IN p_code text, IN p_name text, IN p_citiesid integer, IN p_user_id integer, INOUT p_id integer, INOUT p_mensaje_resultado text)
 LANGUAGE plpgsql
AS $procedure$
DECLARE v_existente integer;
BEGIN
    SELECT id INTO v_existente FROM public."Airports" WHERE "code" = p_code;
    IF v_existente IS NOT NULL THEN p_mensaje_resultado := 'ERROR: El código ya existe.'; RETURN; END IF;
    INSERT INTO public."Airports" ("code", "name", "citiesId") VALUES (COALESCE(TRIM(p_code), ''), TRIM(p_name), p_citiesId) RETURNING id INTO p_id;
    p_mensaje_resultado := 'SUCCESS';
EXCEPTION WHEN OTHERS THEN p_mensaje_resultado := 'ERROR: ' || SQLERRM; p_id := 0; END; $procedure$

spbranchcrear.definition:
CREATE OR REPLACE PROCEDURE public.spbranchcrear(IN p_code text, IN p_name text, IN p_logo bytea, IN p_template bytea, IN p_template_config jsonb, IN p_html_template text, IN p_resolution_id integer DEFAULT NULL::integer, IN p_invoice_template bytea DEFAULT NULL::bytea, IN p_invoice_template_config jsonb DEFAULT NULL::jsonb, IN p_invoice_html_template text DEFAULT NULL::text, IN p_is_active boolean DEFAULT true, IN p_acting_user_id integer DEFAULT 1, INOUT p_branch_id integer DEFAULT 0, INOUT p_mensaje_resultado text DEFAULT ''::text)
 LANGUAGE plpgsql
AS $procedure$
BEGIN
    INSERT INTO public."Branch" (
        "code", "name", "logo", "template", "templateConfig", "htmlTemplate",
        "resolutionId", "invoiceTemplate", "invoiceTemplateConfig", "invoiceHtmlTemplate", "isActive"
    )
    VALUES (
        p_code, p_name, p_logo, p_template, p_template_config, p_html_template,
        p_resolution_id, p_invoice_template, p_invoice_template_config, p_invoice_html_template, COALESCE(p_is_active, true)
    )
    RETURNING id INTO p_branch_id;

    p_mensaje_resultado := 'SUCCESS: Sucursal creada con ID ' || p_branch_id;
EXCEPTION
    WHEN OTHERS THEN
        p_mensaje_resultado := 'ERROR: ' || SQLERRM;
END;
$procedure$

spbrancheliminar.definition:
CREATE OR REPLACE PROCEDURE public.spbrancheliminar(IN p_id integer, IN p_acting_user_id integer, INOUT p_mensaje_resultado text)
 LANGUAGE plpgsql
AS $procedure$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public."Branch" WHERE id = p_id) THEN
        p_mensaje_resultado := 'ERROR: Sucursal con ID ' || p_id || ' no encontrada.';
        RETURN;
    END IF;

    DELETE FROM public."Branch" WHERE id = p_id;
    p_mensaje_resultado := 'SUCCESS: Sucursal eliminada exitosamente.';
EXCEPTION
    WHEN OTHERS THEN
        p_mensaje_resultado := 'ERROR: ' || SQLERRM;
END;
$procedure$

spcellcustomizationdelete.definition:
CREATE OR REPLACE PROCEDURE public.spcellcustomizationdelete(IN p_code text, IN p_branch_id integer, IN p_implant_id integer)
 LANGUAGE plpgsql
AS $procedure$
BEGIN
    IF p_branch_id IS NOT NULL THEN
        DELETE FROM public."CellCustomization"
        WHERE "code" = p_code AND "branchId" = p_branch_id AND "implantId" IS NULL;
    ELSIF p_implant_id IS NOT NULL THEN
